class ListNode:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next


def arr_to_list(arr):
    head = None
    tail = None
    for val in arr:
        node = ListNode(val)
        if not head:
            head, tail = node, node
        else:
            tail.next = node
            tail = node
    return head


def list_to_arr(head):
    result = []
    node = head
    while node:
        result.append(node.val)
        node = node.next
    return result


def remove_nth_from_end(head_arr, n):
    head = arr_to_list(head_arr)
    dummy = ListNode(0, head)
    fast = dummy
    slow = dummy

    for _ in range(n + 1):
        fast = fast.next

    while fast:
        fast = fast.next
        slow = slow.next

    slow.next = slow.next.next
    return list_to_arr(dummy.next)

